begin;
create extension if not exists pgcrypto;
create table if not exists public.angelcare_marketplace_partner_tenants(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('TEN-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),tenant_code text unique not null,legal_name text not null,display_name text not null,tenant_type text not null,territory_id uuid,status text not null default 'draft' check(status in('draft','onboarding','trial','active','suspended','cancelled','archived')),owner_id uuid,default_locale text not null default 'fr' check(default_locale in('fr','en','ar')),currency_label text not null default 'Dh',onboarding_score int not null default 0 check(onboarding_score between 0 and 100),health_status text not null default 'unknown' check(health_status in('healthy','attention','at_risk','critical','unknown')),created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_partner_domains(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.angelcare_marketplace_partner_tenants(id) on delete cascade,domain text unique not null,status text not null default 'pending' check(status in('pending','verified','active','failed','archived')),verification_token text,verified_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_partner_plans(id uuid primary key default gen_random_uuid(),plan_key text unique not null,name_fr text not null,description_fr text,billing_period text not null default 'monthly' check(billing_period in('monthly','quarterly','annual','custom')),base_price numeric(16,2),currency_label text not null default 'Dh',status text not null default 'draft' check(status in('draft','review','approved','published','paused','archived')),sort_order int not null default 0,owner_id uuid,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_partner_plan_modules(id uuid primary key default gen_random_uuid(),plan_id uuid not null references public.angelcare_marketplace_partner_plans(id) on delete cascade,module_key text not null,included boolean not null default true,usage_limit jsonb not null default '{}',configuration_template jsonb not null default '{}',sort_order int not null default 0,unique(plan_id,module_key));
create table if not exists public.angelcare_marketplace_partner_subscriptions(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('SUB-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),tenant_id uuid not null references public.angelcare_marketplace_partner_tenants(id),plan_id uuid not null references public.angelcare_marketplace_partner_plans(id),status text not null default 'draft' check(status in('draft','trial','active','past_due','suspended','cancelled','expired')),starts_at timestamptz,trial_ends_at timestamptz,current_period_starts_at timestamptz,current_period_ends_at timestamptz,renewal_mode text not null default 'manual' check(renewal_mode in('manual','automatic','contractual')),amount numeric(16,2),currency_label text not null default 'Dh',cancel_reason text,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_partner_module_activations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.angelcare_marketplace_partner_tenants(id) on delete cascade,module_key text not null,status text not null default 'configured' check(status in('configured','pending_approval','active','suspended','archived')),activated_at timestamptz,deactivated_at timestamptz,configuration jsonb not null default '{}',usage_limit jsonb not null default '{}',approved_by uuid,approved_at timestamptz,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,module_key));
create table if not exists public.angelcare_marketplace_partner_tenant_members(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.angelcare_marketplace_partner_tenants(id) on delete cascade,app_user_id uuid not null,role_key text not null,active boolean not null default true,invited_by uuid,invited_at timestamptz not null default now(),accepted_at timestamptz,updated_at timestamptz not null default now(),unique(tenant_id,app_user_id,role_key));
create table if not exists public.angelcare_marketplace_partner_usage_limits(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.angelcare_marketplace_partner_tenants(id) on delete cascade,module_key text not null,metric_key text not null,limit_value numeric(18,4) not null,period text not null default 'monthly' check(period in('daily','monthly','annual','lifetime')),status text not null default 'active' check(status in('active','paused','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,module_key,metric_key,period));
create table if not exists public.angelcare_marketplace_partner_usage_counters(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.angelcare_marketplace_partner_tenants(id) on delete cascade,module_key text not null,metric_key text not null,period_key text not null,current_value numeric(18,4) not null default 0,limit_value numeric(18,4),limit_status text not null default 'within_limit' check(limit_status in('within_limit','warning','exceeded','unlimited')),last_recorded_at timestamptz not null default now(),unique(tenant_id,module_key,metric_key,period_key));
create table if not exists public.angelcare_marketplace_partner_onboarding_checks(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.angelcare_marketplace_partner_tenants(id) on delete cascade,check_key text not null,title_fr text not null,description_fr text,required boolean not null default true,status text not null default 'not_started' check(status in('not_started','in_progress','submitted','passed','failed','waived','not_applicable')),owner_id uuid,reviewer_id uuid,evidence jsonb not null default '[]',blocker_reason text,sort_order int not null default 0,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,check_key));
create table if not exists public.angelcare_marketplace_partner_tenant_audit_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.angelcare_marketplace_partner_tenants(id) on delete cascade,event_type text not null,object_type text,object_id text,actor_id uuid,before_value jsonb,after_value jsonb,reason text,created_at timestamptz not null default now());
create or replace function public.angelcare_marketplace_create_partner_tenant(p_payload jsonb,p_actor_id uuid,p_territory_id uuid) returns public.angelcare_marketplace_partner_tenants language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_partner_tenants;begin insert into public.angelcare_marketplace_partner_tenants(tenant_code,legal_name,display_name,tenant_type,territory_id,status,owner_id,default_locale,currency_label,created_by,updated_by) values(coalesce(nullif(p_payload->>'tenant_code',''),'TEN-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))),p_payload->>'legal_name',coalesce(p_payload->>'display_name',p_payload->>'legal_name'),coalesce(p_payload->>'tenant_type','establishment'),p_territory_id,'onboarding',p_actor_id,coalesce(p_payload->>'default_locale','fr'),coalesce(p_payload->>'currency_label','Dh'),p_actor_id,p_actor_id) returning * into r;insert into public.angelcare_marketplace_partner_onboarding_checks(tenant_id,check_key,title_fr,description_fr,required,sort_order) values(r.id,'identity.verified','Identité légale vérifiée','Confirmer la raison sociale et les documents.',true,10),(r.id,'subscription.active','Plan et abonnement confirmés','Affecter un plan et activer la période.',true,20),(r.id,'modules.configured','Modules configurés','Configurer les modules autorisés.',true,30),(r.id,'members.assigned','Équipe tenant affectée','Inviter et affecter les rôles tenant.',true,40),(r.id,'security.reviewed','Isolation et sécurité revues','Valider le périmètre tenant.',true,50),(r.id,'launch.approved','Activation approuvée','Décision finale de mise en service.',true,60);return r;end$$;
create index if not exists angelcare_partner_tenants_status_idx on public.angelcare_marketplace_partner_tenants(status,territory_id,updated_at desc);create index if not exists angelcare_partner_subscriptions_renewal_idx on public.angelcare_marketplace_partner_subscriptions(status,current_period_ends_at);
insert into public.angelcare_marketplace_permissions(permission_key,name,category,sensitive) values
('marketplace.partner_os.public.view','Voir Partner OS public','Partner OS',false),('marketplace.partner_os.admin.view','Voir Partner OS Command','Partner OS',false),('marketplace.partner_os.tenants.create','Créer un tenant','Partner OS',true),('marketplace.partner_os.tenants.manage','Gérer les tenants','Partner OS',true),('marketplace.partner_os.plans.view','Voir les plans','Partner OS',false),('marketplace.partner_os.plans.manage','Gérer les plans','Partner OS',true),('marketplace.partner_os.subscriptions.view','Voir les abonnements','Partner OS',false),('marketplace.partner_os.subscriptions.manage','Gérer les abonnements','Partner OS',true),('marketplace.partner_os.modules.manage','Gérer les modules tenant','Partner OS',true),('marketplace.partner_os.usage.view','Voir les usages','Partner OS',false),('marketplace.partner_os.usage.manage','Gérer les limites','Partner OS',true),('marketplace.partner_os.onboarding.manage','Gérer l’onboarding','Partner OS',true),('marketplace.partner_os.tenant.access','Accéder au workspace tenant','Partner OS',false),('marketplace.partner_os.tenant.members.manage','Gérer les membres tenant','Partner OS',true),('marketplace.partner_os.export','Exporter les preuves tenant','Partner OS',true)
on conflict(permission_key) do update set name=excluded.name,category=excluded.category,sensitive=excluded.sensitive;
insert into public.angelcare_marketplace_roles(role_key,name,description,system_role,active) values('marketplace_tenant_admin','Administrateur tenant','Administration limitée au tenant affecté.',true,true),('marketplace_partner_manager','Partner OS Manager','Gouvernance des tenants, plans et abonnements.',true,true) on conflict(role_key) do update set name=excluded.name,description=excluded.description,active=true;
insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select 'marketplace_tenant_admin',permission_key from public.angelcare_marketplace_permissions where permission_key in('marketplace.partner_os.tenant.access','marketplace.partner_os.usage.view','marketplace.partner_os.subscriptions.view','marketplace.partner_os.plans.view') on conflict do nothing;
insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select r.role_key,p.permission_key from public.angelcare_marketplace_roles r cross join public.angelcare_marketplace_permissions p where r.role_key in('marketplace_super_admin','marketplace_executive','marketplace_partner_manager') and p.permission_key like 'marketplace.partner_os.%' on conflict do nothing;
update public.angelcare_marketplace_modules set status='enabled',enabled=true,health_status='healthy',route_prefix='/angelcare-marketplace/admin/partner-os',required_permissions=array['marketplace.partner_os.admin.view']::text[],version=version+1,updated_at=now() where module_key='marketplace.partner-os' or introduced_by_mega_zip=11;
insert into public.angelcare_marketplace_feature_flags(flag_key,name,description,enabled,status,reason) values('marketplace.partner-os.enabled','Partner OS','Tenants, plans, abonnements, modules, membres, usages et onboarding.',true,'active','Ultra Delivery 2/5') on conflict(flag_key) do update set enabled=true,status='active',reason=excluded.reason,updated_at=now();
alter table public.angelcare_marketplace_partner_tenants enable row level security;alter table public.angelcare_marketplace_partner_domains enable row level security;alter table public.angelcare_marketplace_partner_plans enable row level security;alter table public.angelcare_marketplace_partner_plan_modules enable row level security;alter table public.angelcare_marketplace_partner_subscriptions enable row level security;alter table public.angelcare_marketplace_partner_module_activations enable row level security;alter table public.angelcare_marketplace_partner_tenant_members enable row level security;alter table public.angelcare_marketplace_partner_usage_limits enable row level security;alter table public.angelcare_marketplace_partner_usage_counters enable row level security;alter table public.angelcare_marketplace_partner_onboarding_checks enable row level security;alter table public.angelcare_marketplace_partner_tenant_audit_events enable row level security;
revoke all on table public.angelcare_marketplace_partner_tenants,public.angelcare_marketplace_partner_domains,public.angelcare_marketplace_partner_plans,public.angelcare_marketplace_partner_plan_modules,public.angelcare_marketplace_partner_subscriptions,public.angelcare_marketplace_partner_module_activations,public.angelcare_marketplace_partner_tenant_members,public.angelcare_marketplace_partner_usage_limits,public.angelcare_marketplace_partner_usage_counters,public.angelcare_marketplace_partner_onboarding_checks,public.angelcare_marketplace_partner_tenant_audit_events from anon,authenticated;
grant all on table public.angelcare_marketplace_partner_tenants,public.angelcare_marketplace_partner_domains,public.angelcare_marketplace_partner_plans,public.angelcare_marketplace_partner_plan_modules,public.angelcare_marketplace_partner_subscriptions,public.angelcare_marketplace_partner_module_activations,public.angelcare_marketplace_partner_tenant_members,public.angelcare_marketplace_partner_usage_limits,public.angelcare_marketplace_partner_usage_counters,public.angelcare_marketplace_partner_onboarding_checks,public.angelcare_marketplace_partner_tenant_audit_events to service_role;
grant execute on function public.angelcare_marketplace_create_partner_tenant(jsonb,uuid,uuid) to service_role;
commit;
